output_text:
[
  {
    "id": "must_get_cart",
    "text": "The shopper is obliged to have a cart at some point during the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The shopper is prohibited from exiting the store without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_at_3_1",
    "text": "The shopper is prohibited from being at cell (3,1) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_interact_3_1",
    "text": "The shopper is prohibited from interacting at cell (3,1) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "no_cart_upper_move",
    "text": "The shopper is prohibited from moving while holding a cart in the upper cells (3,1) or (3,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "MOVE",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_north_from_3_3",
    "text": "The shopper is prohibited from moving north from cell (3,3) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "park_cart_at_3_3",
    "text": "Whenever the shopper reaches cell (3,3) with a cart, they are obliged to put the cart down.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          "hasCart"
        ]
      },
      "discharge": {
        "not": "hasCart"
      }
    }
  },
  {
    "id": "reclaim_after_3_1",
    "text": "After visiting cell (3,1), the shopper is obliged to regain a cart before the trip ends.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "at(3,1)",
      "discharge": "hasCart"
    }
  }
]
